mapper.update:
UPDATE t_risk_variable SET variable_name=#{change.variableName}, description=#{change.description},
string_value=#{change.values.stringValue}, number_value=#{change.values.numberValue}, boolean_value=#{change.values.booleanValue},
datetime_value=#{change.values.datetimeValue}, duration_value=#{change.values.durationValue}, status=#{change.status},
version=version+1, update_by=#{actorId}, update_time=#{time}
WHERE variable_code=#{root.variableCode} AND version=#{root.version}

mapper.select:
SELECT  FROM t_risk_variable_member 
ORDER BY sort_order, member_id LIMIT #{limit} OFFSET #{offset}
FOR SHARE

SELECT  FROM (
    SELECT , ROW_NUMBER() OVER (PARTITION BY variable_code ORDER BY sort_order,member_id) AS row_no
    FROM t_risk_variable_member WHERE variable_code IN
    #{code}
) ranked WHERE row_no <= #{limit} ORDER BY variable_code,sort_order,member_id
